import math
import gc
import torch
import pandas as pd
from tqdm import tqdm

CHUNK_SIZE = 50000

TOTAL_ROWS = len(df)

TOTAL_CHUNKS = math.ceil(TOTAL_ROWS / CHUNK_SIZE)

print("Total Rows :", TOTAL_ROWS)
print("Chunk Size :", CHUNK_SIZE)
print("Total Chunks :", TOTAL_CHUNKS)

import time
import gc
import torch

for chunk_id in range(1, TOTAL_CHUNKS):

    print("=" * 80)
    print(f"Processing Chunk {chunk_id + 1}/{TOTAL_CHUNKS}")

    start_idx = chunk_id * CHUNK_SIZE
    end_idx = min((chunk_id + 1) * CHUNK_SIZE, TOTAL_ROWS)

    chunk = (
        df.iloc[start_idx:end_idx]
        .drop(columns=["doc_length"], errors="ignore")
        .reset_index(drop=True)
    )

    start = time.time()

    embeddings = model.encode(
        chunk["document"].tolist(),
        batch_size=512,
        show_progress_bar=True,
        convert_to_numpy=True,
        normalize_embeddings=True
    )

    embedding_df = pd.DataFrame({
        "parent_asin": chunk["parent_asin"],
        "category": chunk["category"],
        "product_title": chunk["product_title"],
        "embedding": embeddings.tolist()
    })

    output_file = f"embedding_chunk_{chunk_id + 1:03d}.parquet"

    embedding_df.to_parquet(output_file, index=False)

    s3.upload_file(
        output_file,
        "ml-data-aws-transformer-bert",
        f"ml/embeddings/all_minilm_l6_v2/{output_file}"
    )

    end = time.time()

    print(f"Chunk {chunk_id + 1} completed.")
    print(f"Rows : {len(chunk)}")
    print(f"Time : {round(end-start,2)} sec")

    del chunk
    del embeddings
    del embedding_df

    gc.collect()
    torch.cuda.empty_cache()

